+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"os"
+	"runtime/debug"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+// Reproduction for urfave/cli#2176: the global HelpFlag is reset and
+// re-applied by every Command.Run, so running commands in parallel races
+// on it and can panic with a nil pointer dereference.
+func issue2176RunCli(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type issue2176Case struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func TestIssue2176ParallelHelpFlag(t *testing.T) {
+	t.Parallel()
+
+	tests := []issue2176Case{
+		{Name: "hello_world", Exit: 0},
+		{Name: "hello_sunshine", Exit: 0},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					if os.Getenv("ISSUE2176_STACK") != "" {
+						t.Logf("stack:\n%s", debug.Stack())
+					}
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			issue2176RunCli(tt.Args)
+		})
+	}
+}
